class DirectoryNotExists(Exception):
    pass


class DirectoryIsEmpty(Exception):
    pass


class HostnameUnavailable(Exception):
    """ Raised when there is no hostname via socket read. """
    pass


class IncorrectBTSType(Exception):
    """ Raised when given BTS type is neither GNB nor ENB. """
    pass


class IncorrectBTSConfiguration(Exception):
    """ Raised when given BTS configuration is incorrect. """
    pass


class FileDoesNotExist(Exception):
    """ Raised when file doesn't exist. """
    pass


class MissingMandatoryObject(Exception):
    """ Raised when missing mandatory object in scf. """
    pass


class SwStreamDoseNotExist(Exception):
    """ Raised when sw_stream doesn't exist in method. """
    pass


class TimeoutError(Exception):
    """
    Classical TimeoutError with broad applications
    """
    pass


class KeywordRetryExceededError(Exception):
    """
    Raised when given retry count for keyword is exceeded.
    """
    pass


class AverageThroughputNotWithinDeviation(Exception):
    """
    Raised when average throughput exceeds limits set by deviation
    """
    pass


class ThroughputMsgsNotFoundInBtslog(Exception):
    """
    Raised when no messages concerning throughput can be found in BTSlog,
    making it impossible to calculate average tput
    """
    pass


class BtslogVerificationFailed(Exception):
    """
    Raised when looked for results aren't present in btslog when they should and/or be present when they shouldn't.
    """
    pass


class LogCollectionError(Exception):
    """
    Raised when given log cannot be collected
    """
    pass


class NoLmpInterfaceDetected(Exception):
    """
    Raised when there is no lmp interface detected.
    """
    pass


class CannotUnpackArchive(Exception):
    """
    Raised when archive cannot be unpacked or it's missing
    """
    pass


class HwNotReachable(Exception):
    """
    Raised when hw not found.
    """
    pass


class SSHCredentialsError(Exception):
    """
    Raised when ssh credentials are incorrect
    """
    pass


class PowerDiffBelowThreshold(Exception):
    """
    Raised when power difference threshold
    measured by measure_power_diff in sign_analyzer.py
    is not exceeded by actual measure.
    """
    pass


class NoCenterFreqForGivenNRARFCN(Exception):
    """
    Raised when there is no center frequency
    for given NRARFCN in Nrarfcn_Fcenter_IF.csv.
    """
    pass


class RatNotSupported(Exception):
    """
    Raised when given RAT technology is not supported.
    """
    pass


class ExceededAllowedTimeRange(Exception):
    """
    Raised when provided time has exceeded allowed range.
    """
    pass


class StringNotFoundInLogFile(Exception):
    """
    Raised when custom string is not found in any .LOG file
    """
    pass


class RfScanShouldNotBeAvailable(Exception):
    """
    Raised when RF scanning procedure is available, although it should not be.
    """
    pass


class RfScanFileNotFoundOrWrongFileName(Exception):
    """
    Raised when RF Scan file not found in directory or file name not started with "RFMonitoring".
    """
    pass


class RfScanFileNameNotCorrect(Exception):
    """
    Raised when RF Scan file name is not correct.
    """
    pass


class RfScanFileSizeNotCorrect(Exception):
    """
    Raised when RF Scan file size is not correct (not bigger than zero).
    """
    pass


class RadioNameNotFoundInProvidedDictionary(Exception):
    """
    Raised when radio name not found in provided dictionary with capture types.
    """
    pass


class FileWithCustomStringNotFound(Exception):
    """
    Raised when file with custom string in name is not found in given smod directory.
    """
    pass


class TooManyFileNamesWithCustomString(Exception):
    """
    Raised when more than one file with custom string in name is found in given smod directory.
    """
    pass


class IncorrectFileSize(Exception):
    """
    Raised when size of file is incorrect.
    """
    pass


class ObjectNotFoundInXmlFile(Exception):
    """
    Raised when object is not in provided xml file.
    """
    pass


class ObjectShouldNotBeFoundInXmlFile(Exception):
    """
    Raised when object is found in provided xml file when should not.
    """
    pass


class LocationInfoNotFoundInXmlFile(Exception):
    """
    Raised when location information is not found in provided xml file.
    """
    pass


class RfStatisticsResultError(Exception):
    """
    Raised when result for rf statistics test is not correct.
    """
    pass


class ObsaiRmodNotSupportedForRfStatistics(Exception):
    """
    Raised when validation is performed for OBSAI rmod.
    """
    pass


class RfDiagnosticResultError(Exception):
    """
    Raised when result for rf statistics test is not correct.
    """
    pass


class NotMatchingTimeFormat(Exception):
    """
    Raised when time data has incorrect format.
    """
    pass


class MissingPortNumber(Exception):
    """
    Raised when port number has not been found.
    """
    pass


class ConnectionAliasNotProvided(Exception):
    """
    Raised when connection alias is not provided.
    """
    pass


class RatTypeError(Exception):
    """
    Raised when RAT type is not correct.
    """
    pass


class RatResetTypeError(Exception):
    """
    Raised when RAT reset type is not correct.
    """
    pass


class BbmodTypeError(Exception):
    """
    Raised when BBMOD type is not implemented.
    """
    pass


class RmodInfoNotFound(Exception):
    """
    Raised when the configured RMOD name could not be found in the get_bts_info['radioModules'] API response.
    """
    pass


class InvalidSerialNumber(Exception):
    """
    Raised when the serial number does not match the pattern.
    """
    pass


class HostIpAddressUnavailable(Exception):
    """
    Raised when host IP address is not available.
    """
    pass


class MissingSwconfigFlag(Exception):
    """
    Raised when swconfig flag is missing.
    """
    pass


class DistNameDoesNotExist(Exception):
    """
    Raised when dist name does not exist.
    """
    pass


class InvalidCellType(Exception):
    """
    Raised when the cell type is invalid or unsupported.
    """
    pass


class ParameterNotFound(Exception):
    """
    Raised when a specific parameter is not found.
    """
    pass
